CREATE OR REPLACE FUNCTION public.user_table_rows_page(_table uuid,_page integer,_q text DEFAULT '',_sort text DEFAULT '',_descending boolean DEFAULT false,_filter text DEFAULT '',_value text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.user_work_tables; numeric_sort boolean; result jsonb; BEGIN
SELECT * INTO t FROM public.user_work_tables WHERE id=_table AND owner_id=auth.uid() AND public.user_workspace_allowed(); IF NOT FOUND THEN RAISE EXCEPTION 'Private table access denied'; END IF;
IF _page<1 OR length(_q)>200 OR length(_value)>200 THEN RAISE EXCEPTION 'Invalid page filter'; END IF;
IF _sort<>'' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t.columns) c WHERE c->>'id'=_sort) THEN RAISE EXCEPTION 'Unknown sort column'; END IF;
IF _filter<>'' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t.columns) c WHERE c->>'id'=_filter) THEN RAISE EXCEPTION 'Unknown filter column'; END IF;
SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(t.columns) c WHERE c->>'id'=_sort AND c->>'type' IN ('number','currency')) INTO numeric_sort;
WITH filtered AS (SELECT * FROM public.user_work_rows r WHERE table_id=t.id AND (_q='' OR strpos(lower(r.values::text),lower(_q))>0) AND (_filter='' OR strpos(lower(coalesce(r.values->>_filter,'')),lower(_value))>0)), page_rows AS (SELECT * FROM filtered ORDER BY CASE WHEN numeric_sort AND NOT _descending THEN nullif(values->>_sort,'')::numeric END ASC NULLS LAST,CASE WHEN numeric_sort AND _descending THEN nullif(values->>_sort,'')::numeric END DESC NULLS LAST,CASE WHEN NOT numeric_sort AND NOT _descending AND _sort<>'' THEN values->>_sort END ASC NULLS LAST,CASE WHEN NOT numeric_sort AND _descending AND _sort<>'' THEN values->>_sort END DESC NULLS LAST,CASE WHEN _sort='' THEN position END,id LIMIT 50 OFFSET (_page-1)*50) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM page_rows p),'[]'::jsonb),'count',(SELECT count(*) FROM filtered)) INTO result;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.user_table_rows_page(uuid,integer,text,text,boolean,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.user_table_rows_page(uuid,integer,text,text,boolean,text,text) TO authenticated,service_role;